mapper.select:
select
    ec.State_Time as ecStateTime,
    mn.*
from Sec_Expert_Check_Dtl mn
left join Sec_Expert_Check ec on ec.id=mn.Ec_Id
left join Sec_Expert ex on ex.Ex_Id=ec.Ex_Id
where mn.Secd_Result=1 and ec.State=7 and ec.Sec_Id=#{secId}
and ex.Ex_Plaintext_Num=#{uPlaintextNum}
and ec.State_Time>=#{latestTime}
order by mn.Secd_Sort asc

mapper.update:
update Sec_Expert_Check_Dtl set Secd_Result=#{res}
where id in

    #{id}
